-- Apply after 001_business_portal.sql. Additive; no admin schema is changed.
begin;
alter table business_portal.fabrics add column if not exists min_stock_quantity numeric(12,1) not null default 0 check(min_stock_quantity>=0);
alter table business_portal.fabrics add column if not exists supplier_id uuid;
create table if not exists business_portal.suppliers(id uuid primary key,owner_id uuid not null references business_portal.owners(id),name text not null,contact text not null default '',email text not null default '',phone text not null default '',created_at timestamptz not null default now());
create table if not exists business_portal.rolls(id uuid primary key,owner_id uuid not null references business_portal.owners(id),fabric_id uuid not null references business_portal.fabrics(id),label text not null,quantity_meters numeric(12,1) not null check(quantity_meters>=0),reserved_meters numeric(12,1) not null default 0 check(reserved_meters>=0 and reserved_meters<=quantity_meters),location text not null default '',dye_lot text not null default '',created_at timestamptz not null default now());
create table if not exists business_portal.passports(id uuid primary key,owner_id uuid not null references business_portal.owners(id),fabric_id uuid not null unique references business_portal.fabrics(id),composition text not null default '',shrinkage_percent numeric(5,2) not null default 0 check(shrinkage_percent between 0 and 100),dye_lot text not null default '',shade text not null default '',care text not null default '',notes text not null default '',photo_data_url text not null default '',created_at timestamptz not null default now());
create table if not exists business_portal.movements(id uuid primary key,owner_id uuid not null references business_portal.owners(id),fabric_id uuid not null references business_portal.fabrics(id),roll_id uuid not null references business_portal.rolls(id),direction text not null check(direction in ('IN','OUT','ADJUST_IN','ADJUST_OUT')),quantity_meters numeric(12,1) not null check(quantity_meters>0),note text not null default '',unit_price numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table if not exists business_portal.designs(id uuid primary key,owner_id uuid not null references business_portal.owners(id),garment_key text not null,garment_name text not null,name text not null,fabric_id uuid not null references business_portal.fabrics(id),measurements jsonb not null,production_sets integer not null check(production_sets>0),wastage_percent numeric(5,2) not null default 0,required_meters numeric(15,1) not null check(required_meters>0),state text not null default 'PLANNED' check(state in ('PLANNED','RESERVED','COMPLETED')),actual_wastage_meters numeric(12,1) not null default 0,created_at timestamptz not null default now());
create table if not exists business_portal.purchases(id uuid primary key,owner_id uuid not null references business_portal.owners(id),supplier_id uuid not null references business_portal.suppliers(id),fabric_id uuid not null references business_portal.fabrics(id),roll_id uuid not null references business_portal.rolls(id),quantity_meters numeric(12,1) not null,unit_price numeric(12,2) not null,reference text not null default '',created_at timestamptz not null default now());
create table if not exists business_portal.reservations(id uuid primary key,owner_id uuid not null references business_portal.owners(id),design_id uuid not null references business_portal.designs(id),roll_id uuid not null references business_portal.rolls(id),quantity_meters numeric(12,1) not null check(quantity_meters>0),state text not null default 'ACTIVE' check(state in ('ACTIVE','CONSUMED')),created_at timestamptz not null default now());
create table if not exists business_portal.procurement(id uuid primary key,owner_id uuid not null references business_portal.owners(id),fabric_id uuid not null references business_portal.fabrics(id),quantity_meters numeric(12,1) not null check(quantity_meters>0),note text not null default '',state text not null default 'DRAFT' check(state='DRAFT'),created_at timestamptz not null default now());
-- Backfill a real opening roll for pre-migration fabrics that lack roll records.
insert into business_portal.rolls(id,owner_id,fabric_id,label,quantity_meters,location)
 select gen_random_uuid(),f.owner_id,f.id,'Opening balance',f.quantity_meters,f.location from business_portal.fabrics f where f.quantity_meters>0 and not exists(select 1 from business_portal.rolls r where r.fabric_id=f.id);
do $$ declare t text;begin
 foreach t in array array['suppliers','rolls','passports','movements','designs','purchases','reservations','procurement'] loop
 execute format('create index if not exists %I on business_portal.%I(owner_id,created_at)',t||'_owner_created_idx',t);
 execute format('alter table business_portal.%I enable row level security',t);
 execute format('revoke all on business_portal.%I from public',t);
 if exists(select 1 from pg_roles where rolname='anon')then execute format('revoke all on business_portal.%I from anon',t);end if;
 if exists(select 1 from pg_roles where rolname='authenticated')then execute format('revoke all on business_portal.%I from authenticated',t);end if;
 end loop;
end $$;
commit;
